const q = (query || '').toLowerCase();
const faq = [
  { keys: ['versand', 'verschick', 'shipping', 'versandkosten'], a: 'Standardversand kostet 3,99 EUR, ab 50 EUR Bestellwert ist der Versand kostenlos.' },
  { keys: ['lieferzeit', 'wie lange', 'wann kommt', 'dauer'], a: 'Die Lieferzeit betraegt in der Regel 2 bis 4 Werktage innerhalb Deutschlands.' },
  { keys: ['rueckgabe', 'rückgabe', 'retoure', 'zurueck', 'zurück', 'umtausch', 'widerruf'], a: 'Du kannst Artikel innerhalb von 30 Tagen kostenlos zurueckgeben. Das Retourenlabel findest du in deinem Kundenkonto.' },
  { keys: ['zahlung', 'bezahlen', 'zahlungsart', 'paypal', 'rechnung', 'kreditkarte', 'klarna'], a: 'Wir akzeptieren PayPal, Kreditkarte, Klarna und Kauf auf Rechnung.' },
  { keys: ['kontakt', 'erreichen', 'telefon', 'email', 'support', 'hotline'], a: 'Unser Support ist Mo bis Fr von 9 bis 17 Uhr unter support@voltbox.de erreichbar.' }
];
for (const item of faq) {
  if (item.keys.some(k => q.includes(k))) {
    return item.a;
  }
}
return 'NICHT_GEFUNDEN';

// Mock-Bestelldatenbank. In T3 wird das durch eine echte Datenquelle ersetzt.
const input = (query || '').toString();
const match = input.match(/\d{4,}/);
const orders = {
  '10001': { status: 'Versendet', tracking: 'DHL 00340434290001', eta: 'morgen' },
  '10002': { status: 'In Bearbeitung', tracking: null, eta: '2 bis 3 Werktage' },
  '10003': { status: 'Zugestellt', tracking: 'DHL 00340434290003', eta: 'bereits erfolgt' },
  '10004': { status: 'Storniert', tracking: null, eta: 'entfaellt' }
};
if (!match) {
  return 'KEINE_BESTELLNUMMER: Es wurde keine Bestellnummer erkannt. Bitte den Kunden nach der Bestellnummer fragen.';
}
const id = match[0];
const o = orders[id];
if (!o) {
  return 'NICHT_GEFUNDEN: Keine Bestellung mit der Nummer ' + id + ' gefunden.';
}
let out = 'Bestellung ' + id + ': Status ' + o.status + '.';
if (o.tracking) { out += ' Tracking: ' + o.tracking + '.'; }
out += ' Voraussichtliche Lieferung: ' + o.eta + '.';
return out;

// Mock-Ticketsystem. In echt waere das ein POST-Request an ein Ticket-Tool.
const text = (query || '').toString().trim();
if (!text) {
  return 'FEHLER: Es wurde kein Anliegen uebergeben.';
}
const ticketId = 'VB-' + Math.floor(100000 + Math.random() * 900000);
return 'Ticket ' + ticketId + ' wurde angelegt. Anliegen: "' + text + '". Ein Mitarbeiter meldet sich innerhalb von 24 Stunden.';
